import requests

BASE_URL = "https://api.socbench.example"

patients_response = requests.get(f"{BASE_URL}/patients")
patients_response.raise_for_status()
patients = patients_response.json()

inventory_response = requests.get(f"{BASE_URL}/inventory")
inventory_response.raise_for_status()
inventory = inventory_response.json()

# Identify critical supplies from patient needs and current inventory.
# Expected data fields are inferred from the endpoint descriptions.
patient_needs = {}
for patient in patients:
    for item in patient.get("required_supplies", []):
        item_id = item.get("item_id") if isinstance(item, dict) else item
        if item_id:
            patient_needs[item_id] = patient_needs.get(item_id, 0) + (
                item.get("quantity", 1) if isinstance(item, dict) else 1
            )

inventory_by_id = {
    item.get("item_id"): item
    for item in inventory
    if isinstance(item, dict) and item.get("item_id")
}

critical_supplies = []
for item_id, needed_quantity in patient_needs.items():
    stock_item = inventory_by_id.get(item_id, {})
    current_quantity = stock_item.get("quantity", stock_item.get("count", 0))
    if current_quantity < needed_quantity:
        critical_supplies.append(
            {
                "item_id": item_id,
                "quantity": needed_quantity - current_quantity,
            }
        )

for supply in critical_supplies:
    update_response = requests.post(
        f"{BASE_URL}/inventory/update",
        json=supply,
    )
    update_response.raise_for_status()

alerts_response = requests.get(f"{BASE_URL}/alerts")
alerts_response.raise_for_status()
active_alerts = alerts_response.json()

print(
    {
        "patients": patients,
        "inventory": inventory,
        "critical_supplies_updated": critical_supplies,
        "active_restocking_alerts": active_alerts,
    }
)

